import sys,json,tempfile,time,queue,hashlib,subprocess
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'scripts'))
from semantic_lsp import LspProcess,MeasurementError
class Trace(LspProcess):
 def __init__(self,*args):self.raw=[];super().__init__(*args)
 def _dispatch(self,body,received_ns):self.raw.append(json.loads(body));return super()._dispatch(body,received_ns)
 def expected_error(self,method,params):
  request_id,_=self.send_request(self.prepare_request(method,params));deadline=time.monotonic()+30
  while True:
   body,received_ns=self.messages.get(timeout=max(0.01,deadline-time.monotonic()))
   if isinstance(body,Exception) or body is None:raise MeasurementError('transport ended during expected error')
   message=json.loads(body)
   if message.get('id')==request_id:
    self.raw.append(message);del self.pending[request_id]
    assert 'error' in message,message
    return message
   self._dispatch(body,received_ns)
 def current_diagnostics(self,uri,version):
  deadline=time.monotonic()+30
  while self.diagnostics.get(uri,{}).get('version')!=version:self._receive(deadline)
  return self.diagnostics[uri]
def offset(text,position):
 lines=text.splitlines(keepends=True);line=position['line'];units=position['character']
 return sum(map(len,lines[:line]))+len(lines[line].encode('utf-16-le')[:units*2].decode('utf-16-le'))
def workspace_edits(edit,uri,version):
 if 'documentChanges' in edit:
  changes=edit['documentChanges'];assert len(changes)==1,edit
  change=changes[0];assert change['textDocument']=={'uri':uri,'version':version},change
  return change['edits']
 assert set(edit)=={'changes'} and set(edit['changes'])=={uri},edit
 return edit['changes'][uri]
def apply_edit(text,edit,uri,version):
 spans=[(offset(text,e['range']['start']),offset(text,e['range']['end']),e['newText']) for e in workspace_edits(edit,uri,version)]
 for start,end,replacement in sorted(spans,reverse=True):text=text[:start]+replacement+text[end:]
 return text
binary=Path('/workspace/target/semantic-approved-126952f6d048/debug/bend2-lsp')
compiler='/tmp/semantic-review-native/bend/bin/bend'
report={'binary_sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'compiler':compiler,'scenarios':[]}
for dependent in [False,True]:
 with tempfile.TemporaryDirectory(prefix='review-hierarchy-wire-') as temporary:
  workspace=Path(temporary)
  shared=('import Base\n\nlaw helper:\n  for x: U32\n  U32\n\ndef f(x: U32) -> U32:\n  helper(x)\n\ndef g(x: U32) -> U32:\n  f(x)\n' if dependent else 'import Base\ndef f(x: U32) -> U32:\n  x\ndef g(x: U32) -> U32:\n  f(x)\n')
  entry=('import Base\nimport ./shared.bend as Shared\n\ndef Shared.helper(x):\n  x\n\ndef main() -> U32:\n  Shared.helper(1)\n' if dependent else 'import Base\nimport ./shared.bend as Shared\ndef main() -> U32:\n  Shared.g(1)\n')
  sources={'shared.bend':shared,'a.bend':entry,'b.bend':entry}
  for name,text in sources.items():(workspace/name).write_text(text)
  shared_uri=(workspace/'shared.bend').as_uri();roots={(workspace/name).as_uri() for name in sources}
  client=Trace(binary,workspace);scenario={'kind':'different-second-hop-meaning' if dependent else 'equivalent-shared-caller','sources':sources}
  try:
   client.compiler_path=compiler;client.settings={'bend2-lsp':{'compilerPath':compiler,'compilerArguments':[]}};client.initialize()
   for name,text in sources.items():
    uri=(workspace/name).as_uri();client.notify('textDocument/didOpen',{'textDocument':{'uri':uri,'languageId':'bend','version':1,'text':text}});client.request('textDocument/documentSymbol',{'textDocument':{'uri':uri}})
   f_line=6 if dependent else 1
   prepared=client.request('textDocument/prepareCallHierarchy',{'textDocument':{'uri':shared_uri},'position':{'line':f_line,'character':4}})[0]
   assert len(prepared)==1,prepared
   calls=client.request('callHierarchy/incomingCalls',{'item':prepared[0]})[0];scenario['prepared']=prepared;scenario['incoming']=calls
   assert len(calls)==(3 if dependent else 1),calls
   call_line=10 if dependent else 4;caller_line=9 if dependent else 3
   for incoming in calls:
    assert incoming['from']['uri']==shared_uri and incoming['from']['name']=='g',incoming
    assert incoming['from']['selectionRange']=={'start':{'line':caller_line,'character':4},'end':{'line':caller_line,'character':5}},incoming
    assert incoming['fromRanges']==[{'start':{'line':call_line,'character':2},'end':{'line':call_line,'character':3}}],incoming
    outgoing=client.request('callHierarchy/outgoingCalls',{'item':incoming['from']})[0]
    assert len(outgoing)==1 and outgoing[0]['to']['uri']==shared_uri and outgoing[0]['to']['name']=='f',outgoing
    assert outgoing[0]['fromRanges']==incoming['fromRanges'],outgoing
    expansion={'root':incoming['from']['data']['rootUri'],'first_hop':outgoing}
    if dependent:
     second=client.request('callHierarchy/outgoingCalls',{'item':outgoing[0]['to']})[0]
     assert len(second)==1 and second[0]['to']['name']=='helper' and second[0]['to']['uri']==expansion['root'],second
     expansion['second_hop']=second
    else:assert expansion['root']==prepared[0]['data']['rootUri'],expansion
    scenario.setdefault('expansions',[]).append(expansion)
   if dependent:assert {call['from']['data']['rootUri'] for call in calls}==roots,calls
   client.finish();scenario['exit']=client.process.returncode
  except BaseException:
   scenario['raw_messages']=client.raw;print(json.dumps({'completed':report,'failed':scenario},ensure_ascii=False,indent=2),file=sys.stderr);raise
  finally:scenario['raw_messages']=client.raw;scenario['stderr']=client.stderr_tail();client.close()
  report['scenarios'].append(scenario)
print(json.dumps(report,ensure_ascii=False,indent=2))

